	public  ArrayList<WriteObject> getReferenceObjects(String key) {
		ArrayList<WriteObject> writeObjects = new ArrayList<WriteObject>();
		if(!refSamples.containsKey(key))
			return writeObjects;
		ArrayList<int[]> samples = (ArrayList<int[]>)refSamples.get(key);
		for(int i=0 ; i<samples.size() ; i++) {
			WriteObject wo = WriteObject.getWriteObjectFromRefSample((int[])samples.get(i));
			writeObjects.add(wo);
		}
		return writeObjects;
		
	}
			

